    "content": "韩国此前展示的Hycore高超音速导弹模型。 据央视新闻报道，韩国总统府青瓦台10月8日通报称，韩国自主研发的高超音速滑翔飞行器（HGV）当天首次试射成功，总统李在明现场观看了此次试射。 通报称，此次试射旨在验证高超音速飞行环境下超高温耐热材料的性能、制导与控制能力，以及低空不规则飞行能力。据了解，高超音速滑翔飞行器利用推进装置加速升至大气层上层后，与推进装置分离，并以较低高度进行滑翔飞行。在当天的试射中，飞行器升至预定高度后成功分离，并在高超音速飞行环境下按计划完成了飞行任务。 高超音速飞行器一般是指‌飞行速度超…"
