    "category": "新闻",
    "title": "中央政法委发布2026年第三季度见义勇为勇士榜 79人上榜",
    "link": "https://www.chinanews.com.cn/sh/2026/10-09/10709462.shtml",
    "pub_date": "2026-10-09 09:30:18",
    "author": "",
    "description": "中新网北京10月9日电 (记者 郭超凯)中央政法委9日在京发布2026年第三季度见义勇为勇士榜。根据见义勇为典型事迹突出程度、网络关注度、各地依法确认和申报意见，进行综合评审评议，共有79位见义勇为勇士获通报表扬和奖励慰问，其中有13位因见义勇为不幸牺牲。",
