    "content": "2026年10月09日 电视剧《云雀叫天录》剧照。 资料图片 \"> 立夏时节，电视剧《主角》以秦腔串起人生故事博得好评；中秋之际，《云雀叫天录》又携皮黄相伴的命运传奇铺展于荧屏之上。戏曲艺术和舞台人生相互交织，电视剧创作在传统文化开掘方面取得新的成果。《云雀叫天录》追溯京剧大师谭鑫培的人生轨迹和求艺经历，但又不限于对人物故事的对位式描摹，而是化谭鑫培为主角孟金福，展现京剧艺术及艺术大师的风采、风貌和风骨，给人以诸多意趣和遐思。 作品举重若轻地描绘了清末京剧艺术的行业生态。在天津戏园里唱戏的孟志道，曾在湖北与丁千里同…"
