    "content": "2026年10月09日 微纪录片《长征二十夜》海报。 资料图片 \"> 在纪念中国工农红军长征胜利90周年之际，微纪录片《长征二十夜》与观众见面了。它以短小精悍、微而不薄的艺术特色，成为同类题材作品中亮眼的网络“轻骑兵”。 作品将厚重的史诗转化为轻量化表达。全篇既有时间纵览的长征全程，也有不同空间的战争截面，人物刻画既展现红军高级干部的运筹帷幄，也关注渡江小战士、苏区百姓的个体命运。每集9分钟，全系列20集，如同一块块色彩斑斓的历史拼图，拼出了一幅波澜壮阔的长征画卷。这样的创作手法，是传统广电适配互联网传播生态的一次…"
