    "content": "2026年10月09日 发行地方政府专项债券（以下简称“专项债”）是实施好更加积极的财政政策的重要抓手。用好债券资金，能够为扩大内需、补齐发展短板、增进民生福祉提供有力资金支撑。近年来，专项债发行规模保持较高水平。如何持续提升资金使用效能，更好服务经济发展与民生改善？记者采访了解到，相关部门正从4方面持续发力。 抓时效 加快债券资金发行使用进度 金秋时节，深南高铁珠三角枢纽机场至省界段建设正酣，架梁、铺轨等工程加快推进，建设团队正全力冲刺年度目标。深南高铁全长约661公里，计划2027年底具备开通条件，届时广东深圳…"
