    "content": "2026年10月09日 本报北京10月8日电&nbsp;&nbsp;（记者韩晓明）多哥部长会议主席福雷·埃索齐姆纳·纳辛贝将于10月9日至16日对中国进行正式访问。外交部发言人毛宁8日在例行记者会上介绍了此访安排。 “福雷主席是中国的老朋友，这是他执政以来第七次正式来华，充分体现多方对发展两国关系的高度重视。”毛宁说，习近平主席将会见福雷主席，李强总理、赵乐际委员长将分别举行会谈会见。福雷主席还将赴陕西、福建、广东等省份参访。 毛宁表示，中国和多哥是全面战略伙伴。建交54年来，两国传统友谊历久弥坚，双方在涉及彼此核…"
