    "content": "2026年10月09日 据新华社马来西亚哥打基纳巴卢10月8日电&nbsp;&nbsp;（杜江帆、徐涛涛）当地时间10月8日，中国海军第四十八批护航编队抵达马来西亚哥打基纳巴卢，开始对马来西亚进行为期5天的友好访问。 上午9时许，悬挂着中马两国国旗的海军唐山舰、大庆舰、太湖舰缓缓驶入哥打基纳巴卢港，官兵在甲板上分区列队，军容严整，精神抖擞，向欢迎人群挥手致意。 马来西亚海军东部舰队官兵代表、中国驻马使领馆工作人员、中资机构及华人华侨代表等在码头迎接，马方军乐队奏响欢迎乐曲，热烈欢迎编队舰艇的到来。 靠泊完毕后，欢迎…"
