    "description": "2026年10月09日 在三洲镇，黄金养带我们去看那片最早的崩岗。72岁的老人脚步很快，脚下的红土被雨水“啃”了几十年，如今踩上去却是实的——树根扎深了，土就“醒”过来了。 长汀水土流失治理经验之所以能走向世界，离不开几代人的接力、技术的攻坚，还有政策的持续托举。更重要的，是一个个跟“黄老汉”一样的普通人。 人民群众是干事创业的主体。黄金养是千万个愿意“跟着干”的农民缩影。政策指了方向，专家递了钥匙，但敢不敢把钱砸进红泥坑、能不能在没挂…",
    "content": "2026年10月09日 在三洲镇，黄金养带我们去看那片最早的崩岗。72岁的老人脚步很快，脚下的红土被雨水“啃”了几十年，如今踩上去却是实的——树根扎深了，土就“醒”过来了。 长汀水土流失治理经验之所以能走向世界，离不开几代人的接力、技术的攻坚，还有政策的持续托举。更重要的，是一个个跟“黄老汉”一样的普通人。 人民群众是干事创业的主体。黄金养是千万个愿意“跟着干”的农民缩影。政策指了方向，专家递了钥匙，但敢不敢把钱砸进红泥坑、能不能在没挂果的前几年咬牙撑住，是群众自己的选择。生态修复的确定性，来自“上下同频”，上面有…"
