    "description": "2026年10月09日 本报北京10月8日电 （记者闫伊乔）近日，教育部办公厅、财政部办公厅联合印发《关于做好2026年银龄讲学计划有关实施工作的通知》，对银龄讲学计划进行部署，义务教育阶段计划招募银龄讲学教师6000名。 2026年银龄讲学计划主要面向脱贫县、欠发达的民族县、革命老区县、边境县以及新疆生产建设兵团团场等实施，重点向国家乡村振兴重点帮扶县倾斜。在此基础上，鼓励各省份结合实际，自主选拔优秀退休教师到其他教育发展薄弱的县乡地…",
    "content": "2026年10月09日 本报北京10月8日电&nbsp;&nbsp;（记者闫伊乔）近日，教育部办公厅、财政部办公厅联合印发《关于做好2026年银龄讲学计划有关实施工作的通知》，对银龄讲学计划进行部署，义务教育阶段计划招募银龄讲学教师6000名。 2026年银龄讲学计划主要面向脱贫县、欠发达的民族县、革命老区县、边境县以及新疆生产建设兵团团场等实施，重点向国家乡村振兴重点帮扶县倾斜。在此基础上，鼓励各省份结合实际，自主选拔优秀退休教师到其他教育发展薄弱的县乡地区开展讲学，根据需要可将普通高中纳入自主实施范围。 通知强…"
