    "content": "2026年10月09日 2023年6月，习近平总书记在文化传承发展座谈会上深刻指出：“‘第二个结合’是又一次的思想解放，让我们能够在更广阔的文化空间中，充分运用中华优秀传统文化的宝贵资源，探索面向未来的理论和制度创新。”这一重要论断收录于《习近平文化文选》第二卷《深刻理解“两个结合”的重大意义》一文中。党的十八大以来，习近平总书记创造性提出并阐述“坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合”，特别是提出“第二个结合”。作为又一次思想解放，“第二个结合”通过创造性转化、创新性发展打破了古今…"
