    "content": "2026年10月09日 千盏灯笼沿街悬挂，橙红色的光在青石板上晕开。来自江西南昌的游客李女士牵着6岁的女儿，在上饶铅山县葛仙村度假区的灯笼街上驻足，将一盏写满心愿的孔明灯托向夜空，周围，3000多盏孔明灯缓缓升空，点亮村落。“我们一家三口写下了愿望，特别有仪式感。”李女士说。 这是葛仙村度假区“千灯盛境”的一幕。这座位于武夷山北麓的山谷，以行进式夜游、实景演艺、非遗体验等沉浸式项目，吸引众多游客前来。 晚上8点40分，近百人的巡游队伍提着鲤鱼灯、转花灯等，穿行于青石小巷间。沿街商铺配合队伍敲锣打鼓，游客身着汉服穿行…"
