    "author": "",
    "description": "2026年10月09日 当地时间10月8日，长春2027第33届世界大学生冬季运动会（以下简称“长春大冬会”）火种采集仪式在意大利都灵举行。乐曲声中，火焰跃动。国际大学生体育联合会主席雷诺·艾德和吉林省长春市市长顾刚共同用1959年首届大运会火炬点燃火种盆，顾刚从火种盆中引火种至长春大冬会火种灯中。这簇火种即将跨越山海，奔赴中国吉林长春。 目前，长春大冬会筹办工作已进入冲刺阶段。从2025年11月长春正式获得第33届世界大学生冬季运动会…",
    "content": "2026年10月09日 当地时间10月8日，长春2027第33届世界大学生冬季运动会（以下简称“长春大冬会”）火种采集仪式在意大利都灵举行。乐曲声中，火焰跃动。国际大学生体育联合会主席雷诺·艾德和吉林省长春市市长顾刚共同用1959年首届大运会火炬点燃火种盆，顾刚从火种盆中引火种至长春大冬会火种灯中。这簇火种即将跨越山海，奔赴中国吉林长春。 目前，长春大冬会筹办工作已进入冲刺阶段。从2025年11月长春正式获得第33届世界大学生冬季运动会承办权以来，不到一年时间，各项关键节点任务相继落地，筹办工作进展顺利。 这是大冬…"
