    "description": "2026年10月09日 新华社记者 孙 非摄 \"> 10月7日晚，国家网球中心钻石球场灯光璀璨。郑钦文用一场胜利重返中网女单八强，为自己的23岁画上圆满句号。 当晚进行的女单第四轮比赛中，郑钦文以6∶1、2∶6、6∶4战胜亚美尼亚球员查拉耶娃，职业生涯第二次闯入中网女单八强。她曾在2024年闯入女单四强，创造个人在中网的最佳战绩。 本场比赛郑钦文迅速进入状态，进攻节奏稳定，首盘以6∶1轻松拿下。第二盘她失误增多，以2∶6被对手扳平。决胜…",
