    "description": "2026年10月09日 中国科学技术大学供图 \"> 新华社记者 周 牧摄 \"> 赵 明摄（影像中国） \"> 今年7月，2025年度国家最高科学技术奖评选结果揭晓，中国科学技术大学1959级技术物理系（02系）校友陈立泉院士获此殊荣。 至此，这个名为“5902”的班级，已走出两名国家最高科学技术奖获得者——陈立泉院士、赵忠贤院士。中国科大1959级校友中，先后已有12人当选两院院士。 济济多士，人才辈出。这份沉甸甸的人才答卷，源于中国科大…",
    "content": "2026年10月09日 中国科学技术大学精准智能化学实验室科研人员在介绍实验设备。 中国科学技术大学供图 \"> “九章四号”量子计算原型机局部。 新华社记者 周 牧摄 \"> 由中国科学技术大学牵头建设的合肥先进光源。 赵 明摄（影像中国） \"> 今年7月，2025年度国家最高科学技术奖评选结果揭晓，中国科学技术大学1959级技术物理系（02系）校友陈立泉院士获此殊荣。 至此，这个名为“5902”的班级，已走出两名国家最高科学技术奖获得者——陈立泉院士、赵忠贤院士。中国科大1959级校友中，先后已有12人当选两院院士…"
