    "pub_date": "2026-10-09 08:26:03",
    "author": "",
    "description": "2026年10月09日 回望数十年科研求索之路，我深耕基础研究的初心，植根于在中国科学技术大学的那段求学岁月。 当年，中国科大践行“全院办校、所系结合”的办学理念，我就读的技术物理系由中国科学院物理研究所直接承办，实现了课堂教学与一线科研的深度衔接，让理论学习不再局限于书本。学校五年本科教育“重固本、强根基”，培养体系循序渐进。入学前三年不分专业，我们专注深耕数理基础，锤炼严谨缜密的理科思维，为后续专业研究筑牢根基。大三下学期，我们整体…",
    "content": "2026年10月09日 回望数十年科研求索之路，我深耕基础研究的初心，植根于在中国科学技术大学的那段求学岁月。 当年，中国科大践行“全院办校、所系结合”的办学理念，我就读的技术物理系由中国科学院物理研究所直接承办，实现了课堂教学与一线科研的深度衔接，让理论学习不再局限于书本。学校五年本科教育“重固本、强根基”，培养体系循序渐进。入学前三年不分专业，我们专注深耕数理基础，锤炼严谨缜密的理科思维，为后续专业研究筑牢根基。大三下学期，我们整体迁入北京中关村地区，进驻物理所各实验室开展实习，在真实的科研场景中积累经验、明晰…"
