    "content": "2026年10月09日 近日，在法国参众两院友华小组支持下，巴黎中国文化中心举办“饶家驹——伟大的和平战士生平展览”，向法国公众介绍这位二战期间在上海保护大批中国平民的法国友人饶家驹（法文原名罗伯特·雅基诺·德·贝桑热）及其人道主义实践。法国吴建民之友协会主席徐波说：“在一个地缘政治越来越占据话语空间的世界里，饶家驹的故事能够让我们重新汲取历史的力量，守护和平的未来。” 今年9月，高约2米的饶家驹纪念铜像在法国西南部城市桑特的公共花园揭幕，以纪念这位法国友人逝世80周年。铜像由上海抗战与世界反法西斯战争研究会代表受…"
