    "content": "新华社伦敦10月8日电（记者张枫）据英国媒体8日报道，两名拉脱维亚男子当天因涉嫌擅闯位于剑桥郡的英国皇家空军莫尔斯沃思基地被捕。 报道称，英国国防部警察7日晚在莫尔斯沃思基地巡逻时发现一辆被遗弃车辆，随即展开调查。数小时后，警方发现基地边缘围栏一处缺口，随后在基地内逮捕两名拉脱维亚男子。 伦敦警察局表示，两人最初因涉嫌闯入禁区及刑事毁坏罪被捕，并被带往剑桥郡一处警察局接受调查。警方随后根据英国《2023年国家安全法》第4条，以涉嫌“进入禁区危害英国利益”为由，对两人追加逮捕。两名嫌疑人均居住在英国，年龄为36岁和3…"
