    "description": "新华社联合国10月8日电 出席第81届联大裁军与国际安全委员会（联大一委）的中国代表团团长、外交部军控司司长孙晓波8日在该委员会一般性辩论发言，指出日本现政权加速“再军事化”，已成为威胁地区和平稳定的突出因素。 孙晓波说，今年是东京审判开庭80周年。当年，日本以承认军国主义罪行、接受《联合国宪章》全部内容为前提加入联合国。但日本现政权否认侵略历史、美化战争罪行、对二战战犯顶礼膜拜，同时持续强军扩武，加速“再军事化”，已成为威胁地区和平稳…",
    "content": "新华社联合国10月8日电 出席第81届联大裁军与国际安全委员会（联大一委）的中国代表团团长、外交部军控司司长孙晓波8日在该委员会一般性辩论发言，指出日本现政权加速“再军事化”，已成为威胁地区和平稳定的突出因素。 孙晓波说，今年是东京审判开庭80周年。当年，日本以承认军国主义罪行、接受《联合国宪章》全部内容为前提加入联合国。但日本现政权否认侵略历史、美化战争罪行、对二战战犯顶礼膜拜，同时持续强军扩武，加速“再军事化”，已成为威胁地区和平稳定的突出因素。日本现职高官公然发表不设禁忌讨论拥有核武器的狂妄言论，企图抛弃“无…"
